import type { ElementTable, RenderElement, RenderSurface } from 'claude-code'

import type { DocPage, FileDoc, GitMark, RepoView } from '../types'

export type ViewerActions = {
  /** Return to the tree. */
  back(): void
  setPage(page: number): void
  /** Markdown rendered <-> source. */
  toggleRaw(): void
  toggleDiff(): void
  /** Show this file in the tree. */
  reveal(): void
  /** Our own close button, beside the engine's ✕. */
  close(): void
}

export type ViewerCtx = {
  surface: RenderSurface
  columns: number
  rows: number
  doc: FileDoc
  /** For text/markdown. */
  page: DocPage | undefined
  /** Loaded only when view.showDiff. */
  diff: { hunks: string; isTruncated: boolean } | undefined
  view: RepoView
  mark?: GitMark
  isTouched: boolean
  /** The repo's folder name: the first crumb of the path. */
  repoName?: string
  actions: ViewerActions
  /** Drawn in place of the body and footer: the pane's keyboard Client, where the surface has one. */
  body?: RenderElement
}

/** Code.source and Markdown.text are refused above 10000 characters. */
const LIMIT = 10000
/** Rows the chrome (header, meta, toolbar, gap, footer, spare) takes around an image. */
const CHROME_ROWS = 6
/** Cells between the divider and the pane's chrome, matching the tree rows' own gutter. */
const PAD = 1
/** `‹ back`. */
const BACK_WIDTH = 6
/** Cells the engine's close mark covers at the right edge, plus a gap and our `close` label. */
const CLOSE_RESERVE = 2 + 5 + 1

/** Rows the hooks-drawn chrome takes above the Client: header, breadcrumb, toolbar with the file's facts. */
export const FILE_CHROME_ROWS = 3

const LANGUAGES: Record<string, string> = {
  ts: 'typescript', tsx: 'typescript', mts: 'typescript', cts: 'typescript',
  js: 'javascript', jsx: 'javascript', mjs: 'javascript', cjs: 'javascript',
  json: 'json', jsonc: 'json', md: 'markdown', mdx: 'markdown', markdown: 'markdown',
  py: 'python', rb: 'ruby', rs: 'rust', go: 'go', java: 'java', kt: 'kotlin',
  swift: 'swift', c: 'c', 'h': 'c', cc: 'c++', cpp: 'c++', hpp: 'c++', cs: 'c#',
  php: 'php', lua: 'lua', sh: 'shell', bash: 'shell', zsh: 'shell', fish: 'shell',
  ps1: 'powershell', sql: 'sql', html: 'html', htm: 'html', css: 'css',
  scss: 'scss', less: 'less', xml: 'xml', svg: 'svg', yaml: 'yaml', yml: 'yaml',
  toml: 'toml', ini: 'ini', env: 'env', txt: 'text', csv: 'csv', tsv: 'tsv',
  vue: 'vue', svelte: 'svelte', graphql: 'graphql', proto: 'protobuf',
  tf: 'terraform', diff: 'diff', patch: 'diff', lock: 'lockfile', log: 'log',
}

const NAMED: Record<string, string> = {
  dockerfile: 'dockerfile', makefile: 'makefile', gemfile: 'ruby', rakefile: 'ruby',
}

function languageOf(path: string): string | undefined {
  const base = path.slice(path.lastIndexOf('/') + 1).toLowerCase()
  const named = NAMED[base]
  if (named) return named
  const dot = base.lastIndexOf('.')
  if (dot <= 0 && !(dot === 0 && base.length > 1)) return undefined

  return LANGUAGES[base.slice(dot + 1)]
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`

  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

/** `abcdefgh` to `abc…fgh` within max characters. */
function middle(s: string, max: number): string {
  if (max <= 0) return ''
  if (s.length <= max) return s
  if (max === 1) return '…'
  const keep = max - 1
  const head = Math.ceil(keep / 2)
  const tail = keep - head

  return s.slice(0, head) + '…' + (tail > 0 ? s.slice(s.length - tail) : '')
}

/** Strips what Code and Markdown refuse (all control characters but tab and newline) and caps the length. */
function clean(text: string): string {
  // eslint-disable-next-line no-control-regex
  return text.replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '').slice(0, LIMIT)
}

function countLines(text: string): number {
  if (text === '') return 0
  let n = 1
  for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) === 10) n++
  if (text.charCodeAt(text.length - 1) === 10) n--

  return n
}

function countDiff(hunks: string): { add: number; del: number } {
  let add = 0
  let del = 0
  for (const line of hunks.split('\n')) {
    const c = line.charCodeAt(0)
    if (c === 43) add++
    else if (c === 45) del++
  }

  return { add, del }
}

function markStyle(mark: GitMark): { color: string; dimColor?: boolean; bold?: boolean } {
  switch (mark) {
    case 'M':
      return { color: 'yellow' }
    case 'A':
      return { color: 'green' }
    case '?':
      return { color: 'green', dimColor: true }
    case 'D':
      return { color: 'red' }
    case 'R':
      return { color: 'cyan' }
    case 'U':
      return { color: 'red', bold: true }
  }
}

export function Viewer(el: ElementTable, ctx: ViewerCtx): RenderElement {
  const { Box, Text, Button, Code, Markdown } = el
  const { doc, view, mark, actions } = ctx
  const columns = Math.max(20, Math.floor(ctx.columns) || 20)
  const pageCount = ctx.page?.pageCount ?? 1
  const current = Math.min(Math.max(view.page, 0), Math.max(0, pageCount - 1))
  const isText = doc.kind === 'text' || doc.kind === 'markdown'
  const isMarkdown = doc.kind === 'markdown'
  // A deleted file has no content to show, only its diff. Keep the toggle
  // reachable while the diff is showing so the person can always get out.
  const hasDiffMark = mark !== undefined && mark !== '?'
  const canDiff = (isText || doc.kind === 'missing') && (hasDiffMark || view.showDiff)
  const showingDiff = canDiff && view.showDiff
  const isPaged = isText && !showingDiff && pageCount > 1

  // 1. Header, the file's tab: back, the file name bold, git mark, touched dot; our close button at
  // the right (the engine's own dim ✕ covers the last two cells of this row, so it stops short of
  // them and the two read as one `close ✕`). One cell in from the divider, as the tree's chrome is.
  const hasClose = columns >= 28
  const tail = (mark ? 2 : 0) + (ctx.isTouched ? 2 : 0)
  const base = doc.path.slice(doc.path.lastIndexOf('/') + 1)
  const baseRoom = Math.max(6, columns - PAD - BACK_WIDTH - 1 - tail - (hasClose ? CLOSE_RESERVE : PAD))
  const header = (
    <Box flexDirection="row" justifyContent="space-between" paddingLeft={PAD} paddingRight={hasClose ? 2 : PAD}>
      <Box flexDirection="row" gap={1}>
        <Button key="back" label="‹ back" plain dimColor onPress={() => actions.back()} />
        <Text bold wrap="truncate-end">{middle(base, baseRoom)}</Text>
        {mark ? <Text {...markStyle(mark)}>{mark}</Text> : null}
        {ctx.isTouched ? <Text color="magenta">●</Text> : null}
      </Box>
      {hasClose ? <Button key="close" plain role="dismiss" label="close" onPress={() => actions.close()} /> : null}
    </Box>
  )

  // 2. Breadcrumb: repo › folders, dim, the last crumb a touch stronger.
  const crumbs = [...(ctx.repoName ? [ctx.repoName] : []), ...doc.path.split('/').slice(0, -1)]
  const crumbRoom = Math.max(4, columns - PAD * 2)
  const crumbText = middle(crumbs.length > 0 ? crumbs.join(' › ') : '·', crumbRoom)
  const breadcrumb = (
    <Box paddingLeft={PAD}>
      <Text dimColor wrap="truncate-end">{crumbText}</Text>
    </Box>
  )

  // 3. Toolbar (only the buttons that apply) with the file's facts at its right edge when they fit.
  const parts: string[] = []
  if (isText) {
    parts.push(`${doc.lineCount} ${doc.lineCount === 1 ? 'line' : 'lines'}`)
    parts.push(formatSize(doc.size))
    const language = languageOf(doc.path)
    if (language) parts.push(language)
    if (isPaged) parts.push(`page ${current + 1}/${pageCount}`)
  } else if (doc.kind === 'image') {
    parts.push('png image', formatSize(doc.size))
  } else if (doc.kind === 'binary' || doc.kind === 'too-large') {
    parts.push(formatSize(doc.size))
  } else if (doc.kind === 'missing') {
    parts.push('not on disk')
  }
  if (showingDiff) {
    if (ctx.diff) {
      const { add, del } = countDiff(ctx.diff.hunks)
      parts.push(`diff vs HEAD +${add} −${del}`)
    } else {
      parts.push('diff vs HEAD')
    }
  }
  const metaText = parts.join(' · ')

  const buttons: RenderElement[] = []
  const labels: string[] = []
  const add = (key: string, label: string, onPress: () => void) => {
    labels.push(label)
    buttons.push(<Button key={key} label={label} plain dimColor onPress={onPress} />)
  }
  if (isPaged && current > 0) add('prev', '‹ prev', () => actions.setPage(current - 1))
  if (isPaged && current < pageCount - 1) add('next', 'next ›', () => actions.setPage(current + 1))
  if (isMarkdown && !showingDiff) add('raw', view.isRaw ? 'rendered' : 'raw', () => actions.toggleRaw())
  if (canDiff) add('diff', showingDiff ? 'file' : 'diff', () => actions.toggleDiff())
  add('reveal', 'reveal', () => actions.reveal())
  const buttonsWidth = labels.reduce((w, l) => w + l.length, 0) + 3 * (labels.length - 1)
  const metaRoom = columns - PAD * 2 - buttonsWidth - 3
  const toolbar = (
    <Box flexDirection="row" justifyContent="space-between" paddingX={PAD}>
      <Box flexDirection="row" flexWrap="wrap" columnGap={3}>
        {buttons}
      </Box>
      {metaRoom >= 8 ? <Text dimColor wrap="truncate-end">{middle(metaText, metaRoom)}</Text> : null}
    </Box>
  )

  // 4. Body.
  let body: RenderElement
  let footer: string | undefined
  if (showingDiff) {
    if (ctx.diff && ctx.diff.hunks.trim() !== '') {
      body = <Code source={clean(ctx.diff.hunks)} format="diff" wrap="truncate-end" />
      if (ctx.diff.isTruncated) footer = '… diff truncated'
    } else {
      body = <Text dimColor>No changes against HEAD.</Text>
    }
  } else if (doc.kind === 'missing') {
    body = <Text dimColor wrap="truncate-end">{doc.error ?? 'File not found.'}</Text>
  } else if (doc.kind === 'too-large') {
    body = <Text dimColor>Too large to show ({formatSize(doc.size)}; the limit is 4.0 MB).</Text>
  } else if (doc.kind === 'binary') {
    body = <Text dimColor>Binary file, not shown.</Text>
  } else if (doc.kind === 'image') {
    if (ctx.surface === 'terminal' && 'Image' in el && doc.absPath) {
      const { Image } = el
      body = (
        <Image
          key="image"
          source={{ file: doc.absPath, format: 'png', generation: Math.floor(doc.mtimeMs) }}
          columns={Math.min(255, Math.max(1, Math.floor(columns)))}
          rows={Math.min(255, Math.max(1, Math.floor(ctx.rows) - CHROME_ROWS))}
          alt={doc.path}
        />
      )
    } else {
      body = <Text dimColor>Image preview is only available in the terminal.</Text>
    }
  } else if (!ctx.page) {
    body = <Text dimColor>Loading…</Text>
  } else if (ctx.page.text === '') {
    body = <Text dimColor>Empty file.</Text>
  } else if (isMarkdown && !view.isRaw) {
    body = <Markdown text={clean(ctx.page.text)} />
  } else {
    body = (
      <Code
        source={clean(ctx.page.text)}
        {...(isMarkdown ? { language: 'markdown', wrap: 'wrap' as const } : { path: doc.path, wrap: 'truncate-end' as const })}
        startLine={ctx.page.startLine}
      />
    )
  }

  // 5. Footer when paged.
  if (isPaged && ctx.page && !footer) {
    const first = ctx.page.startLine
    const last = first + Math.max(1, countLines(ctx.page.text)) - 1
    footer = `lines ${first}–${last} of ${doc.lineCount}`
  }

  if (ctx.body) {
    return (
      <Box flexDirection="column">
        {header}
        {breadcrumb}
        {toolbar}
        {ctx.body}
      </Box>
    )
  }

  return (
    <Box flexDirection="column">
      {header}
      {breadcrumb}
      {toolbar}
      <Box flexDirection="column" marginTop={1}>
        {body}
      </Box>
      {footer ? <Text dimColor wrap="truncate-end">{footer}</Text> : null}
    </Box>
  )
}

files.hooks/nav.tsx:
// repoviewer's keyboard Client: ONE surface module that draws the pane body and
// takes the person's keys once a click has focused it. Tree mode (arrow-key
// navigation, scrolling window, git marks) lives here; file mode (viewer and
// editor) is delegated to ./navfile. The hooks module answers the ops posted
// from here and sends back fresh props.
//
// Rules this file keeps (engine): elements only from `surface.elements`, no `$`,
// one post per key press, setState only from handlers, once on init, or once per
// change of props (guarded), every drawn line one terminal line within
// `props.columns`.
import type { ClientKeyEvent, ClientPointerEvent, ClientSurface, RenderElement } from 'claude-code'
import type { GitMark, NavOp, NavProps, NavRow } from '../types'
import { fileKey, filePointer, fileRender, initFile } from './navfile'
import type { FileState } from './navfile'

export type NavState = {
  /** The path highlighted in the tree. */
  cursor: string
  /** The last `props.cursorAt` adopted. */
  cursorAt: number
  /** First tree row drawn (index into props.tree.rows). */
  top: number
  /** File mode's state (viewer / editor), created from props.file. */
  file: FileState | undefined
  /** The props last adopted from. */
  lastProps: NavProps
  /** `path|mtimeMs|lineAt` of the file adopted into `file` ('' none): adoption happens once per change. */
  fileSeen: string
}

// ---------------------------------------------------------------- text helpers

const ELLIPSIS = '…'

/** Terminal cells a code point takes: 0 combining, 2 wide, else 1. */
function cellWidth(cp: number): number {
  if (cp === 0) return 0
  if (cp < 0x300) return 1
  if (
    (cp >= 0x300 && cp <= 0x36f) ||
    (cp >= 0x200b && cp <= 0x200f) ||
    (cp >= 0xfe00 && cp <= 0xfe0f) ||
    cp === 0x20e3
  ) {
    return 0
  }
  if (
    (cp >= 0x1100 && cp <= 0x115f) ||
    (cp >= 0x2e80 && cp <= 0xa4cf) ||
    (cp >= 0xac00 && cp <= 0xd7a3) ||
    (cp >= 0xf900 && cp <= 0xfaff) ||
    (cp >= 0xfe30 && cp <= 0xfe6f) ||
    (cp >= 0xff00 && cp <= 0xff60) ||
    (cp >= 0xffe0 && cp <= 0xffe6) ||
    (cp >= 0x1f300 && cp <= 0x1faff) ||
    (cp >= 0x20000 && cp <= 0x3fffd)
  ) {
    return 2
  }
  return 1
}

function strWidth(s: string): number {
  let w = 0
  for (const ch of s) w += cellWidth(ch.codePointAt(0) ?? 0)
  return w
}

/** Truncate with a trailing ellipsis so the result is at most `max` cells. */
function fit(s: string, max: number): string {
  if (max <= 0) return ''
  if (strWidth(s) <= max) return s
  if (max === 1) return ELLIPSIS
  let out = ''
  let w = 0
  for (const ch of s) {
    const cw = cellWidth(ch.codePointAt(0) ?? 0)
    if (w + cw > max - 1) break
    out += ch
    w += cw
  }
  return out + ELLIPSIS
}

/** One drawn character: its text, cells, and whether the query matched it. */
type Glyph = { s: string; w: number; hit: boolean }

/** Ranges are flat [start, end, start, end…] UTF-16 offsets into `text`. Control characters become '?'. */
function glyphsOf(text: string, ranges: readonly number[] | undefined): Glyph[] {
  const out: Glyph[] = []
  let at = 0
  for (const ch of text) {
    const cp = ch.codePointAt(0) ?? 0
    const isControl = cp < 32 || (cp >= 127 && cp < 160)
    let hit = false
    if (ranges) {
      for (let i = 0; i + 1 < ranges.length; i += 2) {
        if (at >= ranges[i]! && at < ranges[i + 1]!) {
          hit = true
          break
        }
      }
    }
    out.push({ s: isControl ? '?' : ch, w: isControl ? 1 : cellWidth(cp), hit })
    at += ch.length
  }
  return out
}

const sumWidth = (g: readonly Glyph[]): number => g.reduce((n, x) => n + x.w, 0)

const ELL: Glyph = { s: ELLIPSIS, w: 1, hit: false }

/** Cut to `max` cells keeping the start (tree names). */
function cutEnd(g: Glyph[], max: number): Glyph[] {
  if (sumWidth(g) <= max) return g
  if (max <= 0) return []
  const out: Glyph[] = []
  let w = 0
  for (const x of g) {
    if (w + x.w > max - 1) break
    out.push(x)
    w += x.w
  }
  out.push(ELL)
  return out
}

/** Cut to `max` cells with the ellipsis in the middle, favouring the tail (the file name). */
function cutMiddle(g: Glyph[], max: number): Glyph[] {
  if (sumWidth(g) <= max) return g
  if (max <= 0) return []
  if (max === 1) return [ELL]
  const room = max - 1
  const headRoom = Math.floor(room / 3)
  const head: Glyph[] = []
  let hw = 0
  for (const x of g) {
    if (hw + x.w > headRoom) break
    head.push(x)
    hw += x.w
  }
  const tail: Glyph[] = []
  let tw = 0
  for (let i = g.length - 1; i >= head.length; i--) {
    const x = g[i]!
    if (tw + x.w > room - hw) break
    tail.unshift(x)
    tw += x.w
  }
  return [...head, ELL, ...tail]
}

// ------------------------------------------------------------------ git marks

type Mark = { ch: string; color: string; dim?: boolean; bold?: boolean }

function markOf(mark: GitMark): Mark {
  switch (mark) {
    case 'M':
      return { ch: 'M', color: 'yellow' }
    case 'A':
      return { ch: 'A', color: 'green' }
    case '?':
      return { ch: '?', color: 'green', dim: true }
    case 'D':
      return { ch: 'D', color: 'red' }
    case 'R':
      return { ch: 'R', color: 'cyan' }
    case 'U':
      return { ch: 'U', color: 'red', bold: true }
  }
}

const GIT_MARKS = 'MA?DRU'

/** A row's flags, parsed. */
type Flags = { isDir: boolean; isOpen: boolean; hasChanges: boolean; isTouched: boolean; mark: GitMark | undefined }

function parseFlags(flags: string): Flags {
  let mark: GitMark | undefined
  for (const ch of flags) if (GIT_MARKS.includes(ch)) mark = ch as GitMark
  return {
    isDir: flags.includes('d'),
    isOpen: flags.includes('o'),
    hasChanges: flags.includes('c'),
    isTouched: flags.includes('t'),
    mark,
  }
}

// ------------------------------------------------------------ tree geometry

/** The most recent props, for listeners registered once. */
let latestProps: NavProps | undefined
/** The most recent state (adopted or committed), for listeners registered once. */
let liveState: NavState | undefined

/** Rows the tree window shows: the region less the `… N more` line when rows were left out. */
function viewRows(props: NavProps): number {
  const reserve = props.tree && props.tree.more > 0 ? 1 : 0
  return Math.max(1, props.rows - reserve)
}

/** Scroll so row `idx` is within the window; also clamps to the list. */
function fitTop(top: number, idx: number, window: number, total: number): number {
  let t = Math.min(top, Math.max(0, total - window))
  if (idx >= 0) {
    if (idx < t) t = idx
    else if (idx >= t + window) t = idx - window + 1
  }
  return Math.max(0, t)
}

function indexOfPath(rows: readonly NavRow[], path: string): number {
  if (path === '') return -1
  for (let i = 0; i < rows.length; i++) if (rows[i]![0] === path) return i
  return -1
}

/** The top the tree is drawn from, for these state and props. */
function topFor(state: NavState, props: NavProps): number {
  const rows = props.tree?.rows ?? []
  return fitTop(state.top, indexOfPath(rows, state.cursor), viewRows(props), rows.length)
}

// ------------------------------------------------------------------ adoption

function fileSeenKey(props: NavProps): string {
  if (props.mode !== 'file' || !props.file) return ''
  return `${props.file.path}|${props.file.mtimeMs}|${props.lineAt}`
}

/**
 * Fold new props into the state. Returns the same object when there is nothing
 * to adopt, so the caller calls setState only when something changed.
 */
function adopt(state: NavState | undefined, props: NavProps): NavState {
  let next: NavState
  if (state === undefined) {
    next = {
      cursor: props.cursor,
      cursorAt: props.cursorAt,
      top: 0,
      file: undefined,
      lastProps: props,
      fileSeen: '',
    }
    next.top = topFor(next, props)
  } else {
    next = state
    // The hooks side moved the cursor (reveal, follow, hotkeys): take it and scroll it into view.
    if (props.cursorAt !== next.cursorAt) {
      const moved: NavState = { ...next, cursor: props.cursor, cursorAt: props.cursorAt, lastProps: props }
      moved.top = topFor(moved, props)
      next = moved
    }
  }

  // The open file: create or refresh the file state once per (path, mtime, line bump).
  const seen = fileSeenKey(props)
  if (seen !== next.fileSeen) {
    const previous = next.file
    const isDirty = !!previous?.buffer?.isDirty
    if (seen === '') {
      // Left file mode. A dirty buffer is never thrown away by the tree coming back.
      next = { ...next, fileSeen: '', file: isDirty ? previous : undefined, lastProps: props }
    } else if (isDirty && previous && props.file && previous.path !== props.file.path) {
      // Never switch away from unsaved edits.
      next = { ...next, fileSeen: seen, lastProps: props }
    } else {
      let file = initFile(props, previous)
      // Same file with unsaved edits: the buffer survives whatever initFile did.
      if (isDirty && previous && file.path === previous.path && !file.buffer?.isDirty) file = previous
      next = { ...next, fileSeen: seen, file, lastProps: props }
    }
  }
  return next
}

// ----------------------------------------------------------------- the rows

/** One styled run of a drawn line. */
type Run = { s: string; color?: string; bold?: boolean; dim?: boolean; strike?: boolean }

const sameStyle = (a: Run, b: Run): boolean =>
  a.color === b.color && a.bold === b.bold && a.dim === b.dim && a.strike === b.strike

/** Merge neighbours of one style so a row stays a handful of nodes. */
function mergeRuns(runs: Run[]): Run[] {
  const out: Run[] = []
  for (const r of runs) {
    if (r.s === '') continue
    const last = out[out.length - 1]
    if (last && sameStyle(last, r)) last.s += r.s
    else out.push({ ...r })
  }
  return out
}

/** Width of the right-hand marker cluster (`● M`) plus one gap cell. */
const MARKER_CELLS = 3
const MARKER_GAP = 1
/** Cells kept clear at the right edge, after the markers. */
const EDGE = 1

/** The styled runs of one tree row, exactly `W` cells wide. */
function rowRuns(row: NavRow, W: number, isFilter: boolean): Run[] {
  const [path, depth, flagText, matches] = row
  const f = parseFlags(flagText)
  const isDeleted = f.mark === 'D'
  const mark = !f.isDir && f.mark ? markOf(f.mark) : undefined
  const hasDirDot = f.isDir && f.hasChanges
  const hasMarker = (!!mark || hasDirDot || f.isTouched) && W >= 14
  // A cell of margin at the right edge, as the chrome above keeps, so the markers never touch it.
  const room = hasMarker ? W - MARKER_CELLS - MARKER_GAP - EDGE : W

  // Left side: one gutter cell, indent, chevron, name.
  let prefix = ' '
  if (!isFilter) {
    prefix += ' '.repeat(Math.min(depth * 2, Math.max(0, Math.floor(room / 2))))
    prefix += f.isDir ? (f.isOpen ? '▾ ' : '▸ ') : '  '
  } else if (f.isDir) {
    prefix += f.isOpen ? '▾ ' : '▸ '
  }
  const prefixW = strWidth(prefix)
  const nameRoom = Math.max(1, room - prefixW)

  let name: string
  if (isFilter) name = path
  else {
    const slash = path.lastIndexOf('/')
    name = (slash >= 0 ? path.slice(slash + 1) : path) + (f.isDir ? '/' : '')
  }
  const raw = glyphsOf(name, isFilter ? matches : undefined)
  const glyphs = isFilter ? cutMiddle(raw, nameRoom) : cutEnd(raw, nameRoom)

  const runs: Run[] = [{ s: prefix, dim: isFilter && f.isDir }]
  for (const g of glyphs) {
    if (isDeleted) runs.push({ s: g.s, color: 'red', strike: true, dim: true })
    else if (g.hit) runs.push({ s: g.s, color: 'cyan', bold: true })
    else runs.push({ s: g.s, dim: isFilter && f.isDir })
  }

  const used = prefixW + sumWidth(glyphs)
  if (hasMarker) {
    runs.push({ s: ' '.repeat(Math.max(0, W - EDGE - MARKER_CELLS - used)) })
    runs.push(f.isTouched ? { s: '●', color: 'magenta' } : { s: ' ' })
    runs.push({ s: ' ' })
    if (mark) runs.push({ s: mark.ch, color: mark.color, dim: mark.dim, bold: mark.bold })
    else if (hasDirDot) runs.push({ s: '•', dim: true })
    else runs.push({ s: ' ' })
    runs.push({ s: ' '.repeat(EDGE) })
  } else {
    runs.push({ s: ' '.repeat(Math.max(0, W - used)) })
  }
  return mergeRuns(runs)
}

function renderTree(surface: ClientSurface<NavState>, state: NavState, props: NavProps): RenderElement {
  const { Box, Text } = surface.elements
  const W = Math.max(1, props.columns)
  const tree = props.tree

  if (!tree) return <Text dimColor>Loading files…</Text>
  if (tree.rows.length === 0) {
    const msg = tree.isFiltering ? `No files match "${tree.query}"` : 'No files in this repo.'
    return (
      <Text dimColor wrap="truncate-end">
        {fit(msg, W)}
      </Text>
    )
  }

  const window = viewRows(props)
  const top = topFor(state, props)
  const end = Math.min(tree.rows.length, top + window)
  const lines: RenderElement[] = []
  for (let i = top; i < end; i++) {
    const row = tree.rows[i]!
    const isCursor = row[0] === state.cursor
    const runs = rowRuns(row, W, tree.isFiltering)
    lines.push(
      <Text key={`r:${row[0]}`} wrap="truncate-end" backgroundColor={isCursor ? 'selectionBg' : undefined}>
        {runs.map(r => (
          <Text color={r.color} bold={r.bold} dimColor={r.dim} strikethrough={r.strike}>
            {r.s}
          </Text>
        ))}
      </Text>,
    )
  }
  // Rows left out of the props: say so once the window reaches the end.
  if (tree.more > 0 && end >= tree.rows.length) {
    lines.push(
      <Text key="more" dimColor wrap="truncate-end">
        {fit(` … ${tree.more.toLocaleString('en-US')} more`, W)}
      </Text>,
    )
  }
  return <Box flexDirection="column">{lines}</Box>
}

// -------------------------------------------------------------- tree input

/** Page size: a screen less one row of overlap. */
const pageOf = (props: NavProps): number => Math.max(1, viewRows(props) - 1)

/** The nearest row above `idx` that is a directory one level up, or -1. */
function parentIndex(rows: readonly NavRow[], idx: number): number {
  const depth = rows[idx]![1]
  if (depth <= 0) return -1
  for (let i = idx - 1; i >= 0; i--) {
    const r = rows[i]!
    if (r[1] === depth - 1 && r[2].includes('d')) return i
    if (r[1] < depth - 1) return -1
  }
  return -1
}

/** Key names the Client receives that are not typed text. */
const SPECIAL_KEYS = new Set([
  'up', 'down', 'left', 'right', 'return', 'enter', 'tab', 'backspace', 'delete', 'home', 'end',
  'pageup', 'pagedown', 'escape', 'esc', 'insert', 'backtab', 'clear',
])

/** Text the person typed (a character, or a paste), as opposed to a key with a name. */
export function typedText(k: ClientKeyEvent): string | undefined {
  if (k.ctrl || k.meta || k.key === '' || SPECIAL_KEYS.has(k.key) || /^f\d+$/.test(k.key)) return undefined
  return k.key === 'space' ? ' ' : k.key
}

/** What a tree key does: the new state and the one op to post (either may be absent).
 * Only named keys navigate; typed text goes to Claude Code's prompt, and ← at the top level hands the keys back. */
function treeKey(state: NavState, k: ClientKeyEvent, props: NavProps): { state: NavState; op?: NavOp } {
  const text = typedText(k)
  if (text !== undefined) return { state, op: { op: 'type', text } }
  const tree = props.tree
  if (k.ctrl || k.meta) return { state }
  if (!tree || tree.rows.length === 0) return k.key === 'left' ? { state, op: { op: 'leave' } } : { state }
  const rows = tree.rows
  const idx = indexOfPath(rows, state.cursor)
  const cur = idx >= 0 ? rows[idx]! : undefined
  const f = cur ? parseFlags(cur[2]) : undefined

  /** Move the highlight to row `to`. */
  const move = (to: number): { state: NavState; op?: NavOp } => {
    const at = Math.max(0, Math.min(rows.length - 1, to))
    const path = rows[at]![0]
    if (path === state.cursor) return { state }
    const moved: NavState = { ...state, cursor: path }
    moved.top = fitTop(topFor(state, props), at, viewRows(props), rows.length)
    return { state: moved, op: { op: 'cursor', path } }
  }

  switch (k.key) {
    case 'up':
      return idx < 0 ? move(0) : move(idx - 1)
    case 'down':
      return idx < 0 ? move(0) : move(idx + 1)
    case 'pageup':
      return move((idx < 0 ? 0 : idx) - pageOf(props))
    case 'pagedown':
      return move((idx < 0 ? 0 : idx) + pageOf(props))
    case 'home':
      return move(0)
    case 'end':
      return move(rows.length - 1)
    case 'right': {
      if (!cur || !f) return move(0)
      if (!f.isDir) return { state, op: { op: 'open', path: cur[0] } }
      if (!f.isOpen) return { state, op: { op: 'expand', path: cur[0] } }
      const next = rows[idx + 1]
      // An expanded dir's first child is the next row, one level deeper.
      if (next && next[1] === cur[1] + 1) return move(idx + 1)
      return { state }
    }
    case 'left': {
      if (!cur || !f) return { state, op: { op: 'leave' } }
      if (f.isDir && f.isOpen) return { state, op: { op: 'collapse', path: cur[0] } }
      const parent = parentIndex(rows, idx)
      // At the repo's top level there is nowhere further out: back to Claude Code's prompt.
      return parent >= 0 ? move(parent) : { state, op: { op: 'leave' } }
    }
    case 'return':
    case 'enter':
      if (!cur || !f) return move(0)
      return { state, op: { op: f.isDir ? 'toggle' : 'open', path: cur[0] } }
  }
  return { state }
}

function treePointer(state: NavState, p: ClientPointerEvent, props: NavProps): { state: NavState; op?: NavOp } {
  const tree = props.tree
  if (p.type !== 'down' || !tree) return { state }
  if (p.y < 0 || p.y >= viewRows(props)) return { state }
  const at = topFor(state, props) + p.y
  const row = tree.rows[at]
  if (!row) return { state }
  const f = parseFlags(row[2])
  // A press on the row already selected acts on it (second click); otherwise it selects.
  if (row[0] === state.cursor) return { state, op: { op: f.isDir ? 'toggle' : 'open', path: row[0] } }
  return { state: { ...state, cursor: row[0], top: topFor(state, props) }, op: { op: 'cursor', path: row[0] } }
}

// ------------------------------------------------------------------ the Client

export default function Nav(props: NavProps, surface: ClientSurface<NavState>): RenderElement {
  latestProps = props

  // Adopt new props into the state: once on init, then once per change.
  const isFirst = surface.state === undefined
  const state = adopt(surface.state, props)
  if (state !== surface.state) surface.setState(state)
  liveState = state

  // Listeners are registered once, while the instance has no state yet. They read the live
  // state and props: `commit` keeps `liveState` current between a press and the next render.
  if (isFirst) {
    const commit = (next: NavState) => {
      liveState = next
      surface.setState(next)
    }
    surface.onKey(k => {
      const st = liveState
      const pr = latestProps
      if (!st || !pr) return
      if (pr.mode === 'file') {
        if (!st.file) return
        let posted: NavOp | undefined
        const file = fileKey(st.file, k, pr, op => {
          posted = op
        })
        if (file !== st.file) commit({ ...st, file })
        if (posted) surface.post(posted)
        return
      }
      const r = treeKey(st, k, pr)
      if (r.state !== st) commit(r.state)
      if (r.op) surface.post(r.op)
    })
    surface.onPointer(p => {
      const st = liveState
      const pr = latestProps
      if (!st || !pr) return
      if (pr.mode === 'file') {
        if (!st.file) return
        let posted: NavOp | undefined
        const file = filePointer(st.file, p, pr, op => {
          posted = op
        })
        if (file !== st.file) commit({ ...st, file })
        if (posted) surface.post(posted)
        return
      }
      const r = treePointer(st, p, pr)
      if (r.state !== st) commit(r.state)
      if (r.op) surface.post(r.op)
    })
  }

  const { Text } = surface.elements
  if (props.mode === 'file') {
    if (!state.file) return <Text dimColor>Loading…</Text>
    return fileRender(surface.elements, state.file, props)
  }
  return renderTree(surface, state, props)
}

files.hooks/navfile.tsx:
// File mode of canopy's keyboard Client (hooks/nav.tsx): the scrolling,
// syntax-highlighted file view with a line cursor, the rendered-markdown view, the diff
// view and the in-pane text editor UI.
//
// Everything here is pure: `fileKey`, `filePointer` and `initFile` return new FileState
// objects (nav.tsx keeps them in surface state) and `fileRender` only reads. The hooks side
// draws the header and toolbar above the Client, so this draws props.rows rows of at most
// props.columns cells: a body (rows - 1 lines) and one dim status line.
import type { ClientElements, ClientKeyEvent, ClientPointerEvent, RenderElement } from 'claude-code'

import type { NavFile, NavOp, NavProps } from '../types'
import { applyKey, displayCol, fromText, scrollIntoView, toText, view } from './editor'
import type { Buffer } from './editor'

export type FileState = {
  path: string
  mtimeMs: number
  /** View mode: the first visible line (1-based, within the file) and the cursor line. */
  top: number
  line: number
  /** Markdown: rendered (default) or source. Diff: first visible hunk. */
  hunk: number
  /** Present while editing. */
  buffer?: Buffer
  /** A save was refused because the file changed on disk: the next ctrl+s forces. */
  isConflict: boolean
  lineAt: number
  // Extras (optional, so nav.tsx need not know them):
  /** Diff: lines already scrolled off the top of the first visible hunk. */
  diffTop?: number
  /** The page the view state refers to (paged files): a change resets the cursor to the page's edge. */
  page?: number
  /** The `at` of the newest notice already seen; only a newer one is shown. */
  noticeAt?: number
  /** The first ctrl+q on a dirty buffer asked; the next one discards. */
  isDiscarding?: boolean
  /** The text of the save last posted: when the file on disk becomes it, the save landed. */
  saved?: string
}

/** Code.source and Markdown.text are refused above 10000 characters. */
const LIMIT = 10000
const BUDGET = 9500

// --------------------------------------------------------------------------- helpers

/** Strips what Code and Markdown refuse (control characters but tab and newline, incl. \r). */
function clean(text: string): string {
  // eslint-disable-next-line no-control-regex
  return text.replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '')
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, n))
}

/** `abcdefgh` to `abcdefg…` within n characters. */
function cut(s: string, n: number): string {
  if (n <= 0) return ''
  if (s.length <= n) return s
  return n === 1 ? '…' : s.slice(0, n - 1) + '…'
}

/** Cuts at n UTF-16 units without splitting a surrogate pair. */
function slice(s: string, n: number): string {
  if (s.length <= n) return s
  const c = s.charCodeAt(n - 1)
  return s.slice(0, c >= 0xd800 && c <= 0xdbff ? n - 1 : n)
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`

  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

let cachedText: string | undefined
let cachedLines: string[] = []

/** The lines of a text (a trailing newline does not make an extra line); memoised on the last text. */
function linesOf(text: string | undefined): string[] {
  if (text === undefined || text === '') return []
  if (text === cachedText) return cachedLines
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  cachedText = text
  cachedLines = lines

  return lines
}

const isTextual = (f: NavFile): boolean => f.kind === 'text' || f.kind === 'markdown'
const isRendered = (f: NavFile): boolean => f.kind === 'markdown' && !f.isRaw && !f.showDiff
const hasDiffView = (f: NavFile): boolean => f.showDiff && (isTextual(f) || f.kind === 'missing')

function dims(props: NavProps): { columns: number; rows: number; body: number } {
  const columns = Math.max(1, Math.floor(props.columns) || 1)
  const rows = Math.max(0, Math.floor(props.rows) || 0)

  return { columns, rows, body: Math.max(0, rows - 1) }
}

/** Gutter: marker, right-aligned number, space. None when the pane is too narrow. */
function gutter(maxLine: number, columns: number): { gw: number; digits: number } {
  const digits = Math.max(2, String(Math.max(1, maxLine)).length)
  const gw = digits + 2

  return columns >= gw + 8 ? { gw, digits } : { gw: 0, digits }
}

/** The file's line range: [start, last] (last < start when empty). */
function extent(f: NavFile): { start: number; lines: string[]; last: number } {
  const start = Math.max(1, Math.floor(f.startLine) || 1)
  const lines = linesOf(f.text)

  return { start, lines, last: start + lines.length - 1 }
}

// --------------------------------------------------------------------------- state

function blank(props: NavProps): FileState {
  return { path: props.file?.path ?? '', mtimeMs: props.file?.mtimeMs ?? 0, top: 1, line: 1, hunk: 0, isConflict: false, lineAt: props.lineAt }
}

/** The view fields kept inside the file and the cursor in the window. Returns `s` when nothing changes. */
function clampView(s: FileState, props: NavProps): FileState {
  const f = props.file
  if (!f || s.buffer) return s
  const { body } = dims(props)
  const viewRows = Math.max(1, body)
  let { top, line, hunk } = s
  let diffTop = s.diffTop ?? 0
  if (hasDiffView(f)) {
    const hunks = parseHunks(f.diff?.hunks ?? '')
    hunk = clamp(hunk, 0, Math.max(0, hunks.length - 1))
    diffTop = clamp(diffTop, 0, Math.max(0, (hunks[hunk]?.length ?? 1) - 2))
  } else if (isTextual(f)) {
    const { start, last } = extent(f)
    const end = Math.max(start, last)
    if (isRendered(f)) {
      top = clamp(top, start, end)
      line = top
    } else {
      line = clamp(line, start, end)
      if (line < top) top = line
      else if (line >= top + viewRows) top = line - viewRows + 1
      top = clamp(top, start, Math.max(start, end - viewRows + 1))
    }
  }
  if (top === s.top && line === s.line && hunk === s.hunk && diffTop === (s.diffTop ?? 0)) return s

  return { ...s, top, line, hunk, diffTop }
}

/** New props for the same file while a buffer is open: the external-change rules. */
function reconcileBuffer(s: FileState, f: NavFile, props: NavProps): FileState {
  let n = s
  const b = s.buffer!
  const note = props.notice
  if (note && note.tone === 'warn' && /changed/i.test(note.text) && note.at > (n.noticeAt ?? 0)) {
    n = { ...n, isConflict: true, noticeAt: note.at }
  }
  if (f.mtimeMs > s.mtimeMs) {
    const text = f.text
    if (text === undefined) {
      n = b.isDirty ? { ...n, isConflict: true } : { ...n, mtimeMs: f.mtimeMs }
    } else if (text === toText(b) || text === s.saved) {
      // The save landed (or the file now equals the buffer): clean, and the new mtime is the base.
      n = { ...n, mtimeMs: f.mtimeMs, isConflict: false, saved: undefined, buffer: { ...b, original: text, isDirty: toText(b) !== text } }
    } else if (!b.isDirty) {
      const nb = fromText(text, b.cursor.row)
      const row = nb.cursor.row
      const col = Math.min(b.cursor.col, (nb.lines[row] ?? '').length)
      n = {
        ...n,
        mtimeMs: f.mtimeMs,
        isConflict: false,
        buffer: { ...nb, cursor: { row, col }, goalCol: displayCol(nb.lines[row] ?? '', col), top: b.top, left: b.left },
      }
    } else {
      n = { ...n, isConflict: true }
    }
  }

  return n
}

/** Brings state up to date with props: the file switched, the page changed, the hooks side moved the line, the file changed on disk. */
function sync(s: FileState, props: NavProps): FileState {
  const f = props.file
  if (!f) return s
  if (f.path !== s.path && !s.buffer?.isDirty) return initFile(props)
  if (f.path !== s.path) return s
  let n = s
  if (n.buffer) {
    if (props.lineAt !== n.lineAt) n = { ...n, lineAt: props.lineAt }
    n = reconcileBuffer(n, f, props)
  } else {
    const { body } = dims(props)
    if (n.page !== undefined && n.page !== f.page) {
      const { start, last } = extent(f)
      n =
        f.page > n.page
          ? { ...n, page: f.page, line: start, top: start }
          : { ...n, page: f.page, line: Math.max(start, last), top: Math.max(start, last - Math.max(1, body) + 1) }
    } else if (n.page === undefined) {
      n = { ...n, page: f.page }
    }
    if (props.lineAt !== n.lineAt) {
      n = { ...n, lineAt: props.lineAt }
      if (props.line !== undefined) n = { ...n, line: props.line, top: props.line - Math.floor(Math.max(1, body) / 3) }
    }
    if (f.mtimeMs !== n.mtimeMs) n = { ...n, mtimeMs: f.mtimeMs }
  }

  return n
}

function settle(s: FileState, props: NavProps): FileState {
  return clampView(sync(s, props), props)
}

/** Call when the open file or its mtime changes (nav.tsx), or with nothing to start. Keeps the view and an open buffer for the same path. */
export function initFile(props: NavProps, previous?: FileState): FileState {
  const f = props.file
  if (!f) return blank(props)
  if (previous && previous.path === f.path) {
    return clampView(sync({ ...previous, mtimeMs: previous.buffer ? previous.mtimeMs : f.mtimeMs }, props), props)
  }
  const { body } = dims(props)
  const start = Math.max(1, Math.floor(f.startLine) || 1)
  let line = start
  let top = start
  if (props.line !== undefined) {
    line = props.line
    top = line - Math.floor(Math.max(1, body) / 3)
  }

  return clampView(
    {
      path: f.path,
      mtimeMs: f.mtimeMs,
      top,
      line,
      hunk: 0,
      isConflict: false,
      lineAt: props.lineAt,
      diffTop: 0,
      page: f.page,
      noticeAt: props.notice?.at ?? 0,
    },
    props,
  )
}

/** The state as fileKey would see it for these props (file switched, page turned, external change applied). nav.tsx may call it to persist what render derived. */
export function syncFile(state: FileState, props: NavProps): FileState {
  return settle(state, props)
}

// --------------------------------------------------------------------------- diff

type Hunk = string[]

/** Splits `git diff` hunks into hunks (each starting with its `@@` header); what precedes the first one is dropped. */
function parseHunks(text: string): Hunk[] {
  if (text === '') return []
  const out: Hunk[] = []
  let cur: Hunk | undefined
  for (const raw of text.split('\n')) {
    const line = clean(raw)
    if (line.startsWith('@@')) {
      cur = [line]
      out.push(cur)
    } else if (cur) {
      cur.push(line)
    }
  }
  if (cur && cur.length > 1 && cur[cur.length - 1] === '') cur.pop()

  return out
}

const HEADER = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)$/

/** A hunk from its header (start lines kept, counts recomputed from the body so a cut hunk still parses) and body lines. */
function buildHunk(header: string, body: string[], oldSkip = 0, newSkip = 0): string[] {
  const m = HEADER.exec(header)
  if (!m) return [header, ...body]
  let oldN = 0
  let newN = 0
  for (const l of body) {
    const c = l.charAt(0)
    if (c === '\\') continue
    if (c !== '+') oldN++
    if (c !== '-') newN++
  }
  const a = Number(m[1]) + oldSkip
  const c = Number(m[2]) + newSkip

  return [`@@ -${a},${oldN} +${c},${newN} @@${m[3] ?? ''}`, ...body]
}

/** The hunk with its first `skip` body lines scrolled off, header renumbered. */
function skipLines(hunk: Hunk, skip: number): string[] {
  const header = hunk[0] ?? ''
  const body = hunk.slice(1)
  let i = 0
  let oldSkip = 0
  let newSkip = 0
  let counted = 0
  while (i < body.length && counted < skip) {
    const c = body[i]!.charAt(0)
    if (c !== '\\') {
      counted++
      if (c !== '+') oldSkip++
      if (c !== '-') newSkip++
    }
    i++
  }
  while (i < body.length && body[i]!.startsWith('\\')) i++

  return buildHunk(header, body.slice(i), oldSkip, newSkip)
}

/** The diff source drawn from hunk `from` (its first `skip` lines scrolled off): whole hunks within the 10000-character limit. */
function diffSource(hunks: Hunk[], from: number, skip: number): string {
  const out: string[] = []
  let chars = 0
  for (let hunkAt = from; hunkAt < hunks.length; hunkAt++) {
    let lines = hunkAt === from && skip > 0 ? skipLines(hunks[hunkAt]!, skip) : hunks[hunkAt]!
    lines = lines.map((l, i) => (i === 0 ? l : slice(l, 400)))
    let size = lines.reduce((n, l) => n + l.length + 1, 0)
    if (size > BUDGET - chars) {
      if (hunkAt !== from) break
      // The first hunk alone is too long: keep its leading lines, with the counts to match.
      const body: string[] = []
      let used = (lines[0]?.length ?? 0) + 40
      for (const l of lines.slice(1)) {
        if (used + l.length + 1 > BUDGET) break
        body.push(l)
        used += l.length + 1
      }
      lines = buildHunk(lines[0] ?? '', body)
      size = lines.reduce((n, l) => n + l.length + 1, 0)
    }
    out.push(...lines)
    chars += size
  }

  return out.join('\n')
}

// --------------------------------------------------------------------------- markdown

const FENCE = /^ {0,3}(`{3,}|~{3,})(.*)$/

/** The fence opener line when line `idx` sits inside a fenced code block, else undefined. */
function fenceOpener(lines: string[], idx: number): string | undefined {
  let open: string | undefined
  let mark = ''
  for (let i = 0; i < idx && i < lines.length; i++) {
    const l = lines[i]!
    const m = FENCE.exec(l)
    if (!m) continue
    const run = m[1]!
    if (open === undefined) {
      if (run.charAt(0) === '`' && (m[2] ?? '').includes('`')) continue
      open = l
      mark = run
    } else if (run.charAt(0) === mark.charAt(0) && run.length >= mark.length && (m[2] ?? '').trim() === '') {
      open = undefined
    }
  }

  return open
}

/** Whether source line `line` continues the paragraph or list item on `prev` (a soft break), which
 * the renderer would otherwise draw as a line break: hard-wrapped prose breaks mid-sentence. */
function continues(prev: string, line: string): boolean {
  const BLOCK = /^\s*([-*+]\s|\d+[.)]\s|#{1,6}\s|>|\||```|~~~|<|(=+|-+|\*+|_+)\s*$)/
  if (prev.trim() === '' || line.trim() === '') return false
  if (/^\s*(#{1,6}\s|\||```|~~~|<)/.test(prev) || /( {2}|\\)$/.test(prev)) return false
  return !BLOCK.test(line)
}

/** The markdown source drawn from line `top`: enough lines to fill `body` rows (the Box clips the rest), within the limit. */
/** Rows a markdown source line is likely to take once rendered `columns` wide: wrapped prose, a
 * table row with its rule, a heading with its gap. An estimate that errs tall, since a Markdown that
 * outgrows its box overprints the rows below it in the terminal rather than clipping. */
function renderedRows(line: string, columns: number): number {
  const text = line.trim()
  if (text === '') return 1
  if (text.startsWith('|')) return 2
  if (/^#{1,6}\s/.test(text)) return 2
  return Math.max(1, Math.ceil((text.length + 4) / Math.max(10, columns - 2)))
}

function markdownSource(f: NavFile, top: number, body: number, columns: number): string {
  const { start, lines } = extent(f)
  const idx = clamp(top - start, 0, Math.max(0, lines.length - 1))
  const opener = fenceOpener(lines, idx)
  const out: string[] = []
  let chars = 0
  let rows = 0
  if (opener !== undefined) {
    out.push(clean(opener))
    chars += out[0]!.length + 1
    rows += 1
  }
  let inTable = false
  for (let i = idx; i < lines.length; i++) {
    const l = slice(clean(lines[i]!), 2000)
    const prev = out[out.length - 1]
    if (prev !== undefined && i > idx && continues(prev, l) && fenceOpener(lines, i) === undefined) {
      const joined = `${prev.trimEnd()} ${l.trim()}`
      const grew = renderedRows(joined, columns) - renderedRows(prev, columns)
      if (rows + grew > body || chars + l.length + 1 > BUDGET) break
      out[out.length - 1] = joined
      chars += l.length + 1
      rows += grew
      continue
    }
    const isRow = l.trim().startsWith('|')
    // A table's top border and header rule.
    const cost = renderedRows(l, columns) + (isRow && !inTable ? 2 : 0)
    if (rows + cost > body && out.length > 0) break
    // A table starts only if it fits whole (a cut one draws as an empty bordered row): else it
    // opens the next screen. One taller than the pane still draws, cut, when it is at the top.
    if (isRow && !inTable && out.length > 0) {
      let end = i
      while (end + 1 < lines.length && lines[end + 1]!.trim().startsWith('|')) end++
      const tableRows = 3 + (end - i + 1) * 2
      if (rows + tableRows > body) break
    }
    if (chars + l.length + 1 > BUDGET && out.length > 0) break
    inTable = isRow
    out.push(l)
    chars += l.length + 1
    rows += cost
  }
  // A fence left open would swallow nothing after it, but keeps the renderer from guessing.
  if (fenceOpener(out, out.length) !== undefined) out.push('```')

  return slice(out.join('\n'), LIMIT)
}

// --------------------------------------------------------------------------- status line

type Seg = { t: string; color?: string; dim?: boolean; bold?: boolean }

const width = (segs: Seg[]): number => segs.reduce((n, s) => n + s.t.length, 0)

/** Cuts the segments to `cols` cells, with an ellipsis where it cut. */
function cutSegs(segs: Seg[], cols: number): Seg[] {
  if (width(segs) <= cols) return segs
  const out: Seg[] = []
  let left = cols
  for (const s of segs) {
    if (left <= 0) break
    if (s.t.length <= left) {
      out.push(s)
      left -= s.t.length
    } else {
      out.push({ ...s, t: cut(s.t, left) })
      break
    }
  }

  return out
}

/** The first candidate that fits `cols`, else the first one cut. */
function pick(cols: number, candidates: Seg[][]): Seg[] {
  for (const c of candidates) if (width(c) <= cols) return c

  return cutSegs(candidates[0] ?? [], cols)
}

const TONE: Record<string, string> = { info: 'green', warn: 'yellow', error: 'red' }

function freshNotice(s: FileState, props: NavProps): Seg[] {
  const n = props.notice
  if (!n || n.at <= (s.noticeAt ?? 0) || n.text === '') return []

  return [{ t: ' · ', dim: true }, { t: n.text, color: TONE[n.tone] ?? 'green' }]
}

/** `head hints · pos tail`, tried with each tail and, for each, with fewer hints (dropped from the right). */
function hintCandidates(head: Seg[], hints: string[], pos: string, tails: Seg[][]): Seg[][] {
  const out: Seg[][] = []
  for (const tail of tails) {
    for (let k = hints.length; k >= 0; k--) {
      const segs: Seg[] = [...head]
      if (k > 0) segs.push({ t: (segs.length > 0 ? ' ' : '') + hints.slice(0, k).join('  '), dim: true })
      if (pos !== '') segs.push({ t: (segs.length > 0 ? ' · ' : '') + pos, dim: true })
      segs.push(...tail)
      out.push(segs)
    }
  }

  return out
}

function renderStatus(el: ClientElements, segs: Seg[]): RenderElement {
  const { Text } = el

  return (
    <Text wrap="truncate-end">
      {' '}
      {segs.map(s => (
        <Text {...(s.color ? { color: s.color } : {})} {...(s.dim ? { dimColor: true } : {})} {...(s.bold ? { bold: true } : {})}>
          {s.t}
        </Text>
      ))}
    </Text>
  )
}

function viewStatus(el: ClientElements, s: FileState, props: NavProps, columns: number): RenderElement {
  const f = props.file
  const notice = freshNotice(s, props)
  const tails: Seg[][] = notice.length > 0 ? [notice, []] : [[]]
  let hints: string[]
  let pos = ''
  if (!f) {
    hints = ['← back']
  } else if (hasDiffView(f)) {
    const hunks = parseHunks(f.diff?.hunks ?? '')
    hints = ['← file', '↑↓ hunk', 'pgdn more']
    if (hunks.length > 0) pos = `hunk ${s.hunk + 1}/${hunks.length}`
    if (f.diff?.isTruncated) tails.unshift([{ t: ' · diff truncated', dim: true }])
  } else if (isTextual(f)) {
    hints = ['← back']
    if (f.isEditable) hints.push('→ edit')
    hints.push('↑↓ move')
    if (f.pageCount > 1) hints.push(`page ${f.page + 1}/${f.pageCount}`)
    pos = `${isRendered(f) ? s.top : s.line}/${f.lineCount}`
  } else {
    hints = ['← back']
  }

  return renderStatus(el, pick(columns, hintCandidates([], hints, pos, tails)))
}

function editStatus(el: ClientElements, s: FileState, props: NavProps, columns: number): RenderElement {
  const b = s.buffer!
  const head: Seg[] = [{ t: 'EDIT', bold: true }]
  const mod: Seg[] = b.isDirty ? [{ t: ' ● modified', color: 'yellow' }] : []
  const pos = `${b.cursor.row + 1}:${displayCol(b.lines[b.cursor.row] ?? '', b.cursor.col) + 1}`
  const msg = s.isDiscarding
    ? { full: 'unsaved changes — ctrl+q again to discard', short: 'unsaved — ctrl+q again to discard' }
    : s.isConflict
      ? { full: 'changed on disk — ctrl+s overwrites', short: 'changed — ctrl+s overwrites' }
      : undefined
  let candidates: Seg[][]
  if (msg) {
    const m = (t: string): Seg => ({ t, color: 'yellow', bold: true })
    candidates = [
      [...head, { t: ' ' }, m(msg.full), { t: ' · ' + pos, dim: true }],
      [...head, { t: ' ' }, m(msg.full)],
      [m(msg.full)],
      [...head, { t: ' ' }, m(msg.short)],
      [m(msg.short)],
    ]
  } else {
    const notice = freshNotice(s, props)
    const tails: Seg[][] = []
    if (notice.length > 0) tails.push([...mod, ...notice])
    tails.push(mod, [])
    candidates = hintCandidates(head, ['ctrl+s save', 'ctrl+q done', 'ctrl+z undo'], pos, tails)
    candidates.push([...head, ...mod])
  }

  return renderStatus(el, pick(columns, candidates))
}

// --------------------------------------------------------------------------- drawing

/** A gutter cell: the cursor line's bright with a marker, the rest dim. */
function cell(el: ClientElements, n: number, digits: number, isCursor: boolean): RenderElement {
  const { Text } = el
  const num = String(n).padStart(digits)
  if (isCursor) {
    return (
      <Text wrap="truncate-end">
        <Text color="cyan">▸</Text>
        <Text bold>{num + ' '}</Text>
      </Text>
    )
  }

  return (
    <Text dimColor wrap="truncate-end">
      {' ' + num + ' '}
    </Text>
  )
}

function message(el: ClientElements, lines: string[], columns: number, body: number): RenderElement {
  const { Box, Text } = el

  return (
    <Box flexDirection="column" height={body} width={columns} flexShrink={0} overflow="hidden">
      {lines.slice(0, body).map(l => (
        <Text dimColor wrap="truncate-end">
          {' ' + cut(l, Math.max(0, columns - 1))}
        </Text>
      ))}
    </Box>
  )
}

function textBody(el: ClientElements, s: FileState, f: NavFile, props: NavProps): RenderElement {
  const { Box, Code } = el
  const { columns, body } = dims(props)
  const { start, lines, last } = extent(f)
  if (lines.length === 0) return message(el, ['Empty file.'], columns, body)
  const { gw, digits } = gutter(Math.max(f.lineCount, last), columns)
  const codeW = Math.max(1, columns - gw)
  const first = s.top - start
  const win = lines.slice(first, first + body)
  const cap = Math.max(codeW + 1, Math.min(400, Math.floor(9900 / Math.max(1, win.length)) - 1))
  // An empty line is drawn as one space so the Code element keeps exactly one row per line.
  const source = win.map(l => slice(clean(l), cap) || ' ').join('\n')

  return (
    <Box flexDirection="row" height={body} width={columns} flexShrink={0} overflow="hidden">
      {gw > 0 ? (
        <Box flexDirection="column" width={gw} flexShrink={0}>
          {win.map((_, i) => cell(el, s.top + i, digits, s.top + i === s.line))}
        </Box>
      ) : null}
      <Box width={codeW} flexShrink={0} overflow="hidden">
        <Code source={source} path={f.path} wrap="truncate-end" />
      </Box>
    </Box>
  )
}

function renderedBody(el: ClientElements, s: FileState, f: NavFile, props: NavProps): RenderElement {
  const { Box, Markdown } = el
  const { columns, body } = dims(props)
  if (extent(f).lines.length === 0) return message(el, ['Empty file.'], columns, body)

  return (
    // minHeight keeps the status line at the pane's foot when the markdown is short; a fixed height
    // with overflow hidden would overprint in the terminal, so the source itself is cut to fit.
    <Box flexDirection="column" width={columns} minHeight={body} flexShrink={0} paddingLeft={1}>
      <Markdown text={markdownSource(f, s.top, body, Math.max(1, columns - 1))} />
    </Box>
  )
}

function diffBody(el: ClientElements, s: FileState, f: NavFile, props: NavProps): RenderElement {
  const { Box } = el
  const { columns, body } = dims(props)
  if (!f.diff) return message(el, ['Loading diff…'], columns, body)
  const hunks = parseHunks(f.diff.hunks)
  if (hunks.length === 0) {
    const raw = clean(f.diff.hunks)
      .split('\n')
      .filter(l => l.trim() !== '')

    return message(el, raw.length === 0 ? ['No changes against HEAD.'] : raw, columns, body)
  }

  return (
    <Box flexDirection="column" height={body} width={columns} flexShrink={0} overflow="hidden">
      {diffRows(el, diffSource(hunks, s.hunk, s.diffTop ?? 0), columns, body)}
    </Box>
  )
}

/** `text` cut to `max` terminal cells (a wide character counts two), tabs as two spaces. */
function cutCells(text: string, max: number): { text: string; cells: number } {
  let out = ''
  let cells = 0
  for (const ch of text.replace(/\t/g, '  ')) {
    const w = displayCol(ch, ch.length)
    if (cells + w > max) break
    out += ch
    cells += w
  }

  return { text: out, cells }
}

/**
 * The diff drawn row by row: a gutter number (the old line for a removed line, else the new one),
 * the line's marker and text coloured, every row padded to the full width. The engine's Code
 * element in diff format leaves cells a shorter row no longer covers as they were, so a diff
 * drawn through it kept stray tails of the rows (or the file view) it replaced.
 */
function diffRows(el: ClientElements, source: string, columns: number, body: number): RenderElement[] {
  const { Text } = el
  const lines = source.split('\n')
  let top = 0
  for (const l of lines) {
    const hunkHead = HEADER.exec(l)
    if (hunkHead) top = Math.max(top, Number(hunkHead[1]), Number(hunkHead[2]))
  }
  const digits = Math.max(2, String(top + lines.length).length)
  const gw = columns >= digits + 10 ? digits + 2 : 0
  const out: RenderElement[] = []
  let oldN = 0
  let newN = 0
  for (const line of lines) {
    if (out.length >= body) break
    const m = HEADER.exec(line)
    if (m) {
      oldN = Number(m[1])
      newN = Number(m[2])
      const head = cutCells(line, columns - 1)
      out.push(
        <Text key={`d${out.length}`} wrap="truncate-end">
          <Text color="cyan" dimColor>{' ' + head.text + ' '.repeat(Math.max(0, columns - 1 - head.cells))}</Text>
        </Text>,
      )
      continue
    }
    const mark = line.charAt(0)
    if (mark === '\\') continue
    const color = mark === '+' ? 'green' : mark === '-' ? 'red' : undefined
    let num: number
    if (mark === '-') num = oldN++
    else if (mark === '+') num = newN++
    else {
      oldN++
      num = newN++
    }
    const shown = mark === '+' || mark === '-' || mark === ' ' ? line.slice(1) : line
    const text = cutCells(shown, Math.max(0, columns - gw - 2))
    const gutterText = gw > 0 ? ' ' + String(num).padStart(digits) + ' ' : ' '
    const pad = ' '.repeat(Math.max(0, columns - gutterText.length - 1 - text.cells))
    out.push(
      <Text key={`d${out.length}`} wrap="truncate-end">
        <Text dimColor>{gutterText}</Text>
        <Text color={color}>{(color ? mark : ' ') + text.text + pad}</Text>
      </Text>,
    )
  }

  return out
}

function editGeom(props: NavProps, b: Buffer): { columns: number; gw: number; digits: number; vr: number; vc: number } {
  const { columns, body } = dims(props)
  const { gw, digits } = gutter(b.lines.length, columns)

  return { columns, gw, digits, vr: Math.max(1, body), vc: Math.max(1, columns - gw) }
}

/** The cursor row split around its cell: before, the character under it (a space at the end of the line), after. */
function splitAt(text: string, col: number): { before: string; ch: string; after: string } {
  let i = 0
  while (i < text.length && displayCol(text, i) < col) {
    const c = text.charCodeAt(i)
    i += c >= 0xd800 && c <= 0xdbff && i + 1 < text.length ? 2 : 1
  }
  if (i >= text.length) return { before: text, ch: ' ', after: '' }
  const c = text.charCodeAt(i)
  const n = c >= 0xd800 && c <= 0xdbff && i + 1 < text.length ? 2 : 1

  return { before: text.slice(0, i), ch: text.slice(i, i + n), after: text.slice(i + n) }
}

function editBody(el: ClientElements, s: FileState, props: NavProps): RenderElement {
  const { Box, Text } = el
  const b0 = s.buffer!
  const { columns, gw, digits, vr, vc } = editGeom(props, b0)
  const b = scrollIntoView(b0, vr, vc)
  const rows = view(b, vr, vc)
  const { body } = dims(props)

  return (
    <Box flexDirection="column" height={body} width={columns} flexShrink={0} overflow="hidden">
      {rows.map(r => {
        const isCursor = r.cursorCol !== undefined
        const g =
          gw > 0 ? (
            <Text dimColor={!isCursor} bold={isCursor}>
              {' ' + String(r.lineNo).padStart(digits) + ' '}
            </Text>
          ) : null
        if (r.cursorCol === undefined) {
          return (
            <Text wrap="truncate-end">
              {g}
              {r.text === '' ? ' ' : r.text}
            </Text>
          )
        }
        const { before, ch, after } = splitAt(r.text, Math.max(0, r.cursorCol))

        return (
          <Text wrap="truncate-end">
            {g}
            {before}
            <Text inverse>{ch}</Text>
            {after}
          </Text>
        )
      })}
    </Box>
  )
}

export function fileRender(el: ClientElements, state: FileState, props: NavProps): RenderElement {
  const { Box } = el
  const s = settle(state, props)
  const f = props.file
  const { columns, rows, body } = dims(props)
  let content: RenderElement
  let status: RenderElement
  if (s.buffer) {
    content = editBody(el, s, props)
    status = editStatus(el, s, props, columns - 1)
  } else {
    status = viewStatus(el, s, props, columns - 1)
    if (!f) {
      content = message(el, ['Nothing open.'], columns, body)
    } else if (hasDiffView(f)) {
      content = diffBody(el, s, f, props)
    } else if (f.kind === 'image') {
      content = message(el, [`PNG image (${formatSize(f.size)}): preview isn't available in the pane.`], columns, body)
    } else if (f.kind === 'binary') {
      content = message(el, [`Binary file, not shown (${formatSize(f.size)}).`], columns, body)
    } else if (f.kind === 'too-large') {
      content = message(el, [`Too large to show (${formatSize(f.size)}; the limit is 4.0 MB).`], columns, body)
    } else if (f.kind === 'missing') {
      content = message(el, ['File not found: it is not on disk.'], columns, body)
    } else if (f.text === undefined) {
      content = message(el, ['Loading…'], columns, body)
    } else if (isRendered(f)) {
      content = renderedBody(el, s, f, props)
    } else {
      content = textBody(el, s, f, props)
    }
  }

  return (
    <Box flexDirection="column" width={columns} height={rows} flexShrink={0} overflow="hidden">
      {rows > 1 ? content : null}
      {status}
    </Box>
  )
}

// --------------------------------------------------------------------------- keys

const NO_MODS = (k: ClientKeyEvent): boolean => !k.ctrl && !k.meta

/** Moves the cursor line, scrolling only as far as needed. */
function setLine(s: FileState, props: NavProps, f: NavFile, line: number): FileState {
  const { body } = dims(props)
  const { start, last } = extent(f)
  const end = Math.max(start, last)
  const viewRows = Math.max(1, body)
  const l = clamp(line, start, end)
  let top = s.top
  if (l < top) top = l
  else if (l >= top + viewRows) top = l - viewRows + 1

  return { ...s, line: l, top: clamp(top, start, Math.max(start, end - viewRows + 1)) }
}

/** Moves a screen's worth: the cursor and the window together. */
function setPage(s: FileState, props: NavProps, f: NavFile, delta: number): FileState {
  const { body } = dims(props)
  const { start, last } = extent(f)
  const end = Math.max(start, last)
  const viewRows = Math.max(1, body)
  const top = clamp(s.top + delta, start, Math.max(start, end - viewRows + 1))
  const line = clamp(s.line + delta, start, end)

  return { ...s, top, line: clamp(line, top, Math.min(end, top + viewRows - 1)) }
}

function enterEdit(s: FileState, props: NavProps, f: NavFile, post: (op: NavOp) => void): FileState {
  if (!f.isEditable || f.text === undefined || f.pageCount > 1) return s
  const { start } = extent(f)
  const row = Math.max(0, (isRendered(f) ? s.top : s.line) - start)
  const b0 = fromText(f.text, row)
  const geo = editGeom(props, b0)
  const b = scrollIntoView({ ...b0, top: clamp(s.top - start, 0, b0.cursor.row) }, geo.vr, geo.vc)
  post({ op: 'edit', path: f.path, isEditing: true })

  return { ...s, buffer: b, mtimeMs: f.mtimeMs, isConflict: false, isDiscarding: false, saved: undefined, noticeAt: props.notice?.at ?? s.noticeAt ?? 0 }
}

function leaveEdit(s: FileState, props: NavProps, post: (op: NavOp) => void): FileState {
  const b = s.buffer!
  const f = props.file
  const start = f ? extent(f).start : 1
  post({ op: 'edit', path: s.path, isEditing: false })
  const next: FileState = { ...s, buffer: undefined, isConflict: false, isDiscarding: false, saved: undefined, line: start + b.cursor.row, top: start + b.top }

  return clampView(next, props)
}

function editKey(s: FileState, k: ClientKeyEvent, props: NavProps, post: (op: NavOp) => void): FileState {
  const b = s.buffer!
  const key = k.key.length === 1 ? k.key.toLowerCase() : k.key
  if (k.ctrl && !k.meta && key === 's') {
    // Nothing to save: stay quiet (a conflict still lets ctrl+s force the buffer over the disk).
    if (!b.isDirty && !s.isConflict) return s.isDiscarding ? { ...s, isDiscarding: false } : s
    const text = toText(b)
    post({ op: 'save', path: s.path, text, baseMtimeMs: s.mtimeMs, force: s.isConflict })

    return { ...s, saved: text, isDiscarding: false, noticeAt: props.notice?.at ?? s.noticeAt }
  }
  if (k.ctrl && !k.meta && key === 'q') {
    if (b.isDirty && !s.isDiscarding) return { ...s, isDiscarding: true }

    return leaveEdit(s, props, post)
  }
  const { vr } = editGeom(props, b)
  let nb = applyKey(b, k, vr)
  const geo = editGeom(props, nb)
  nb = scrollIntoView(nb, geo.vr, geo.vc)
  if (nb === b) return s.isDiscarding ? { ...s, isDiscarding: false } : s

  return { ...s, buffer: nb, isDiscarding: false, noticeAt: nb.lines !== b.lines ? (props.notice?.at ?? s.noticeAt) : s.noticeAt }
}

/** Keys that are not text: everything else without ctrl/meta is typing and belongs to Claude Code's prompt. */
const SPECIAL = new Set([
  'up', 'down', 'left', 'right', 'return', 'enter', 'tab', 'backspace', 'delete', 'home', 'end', 'pageup', 'pagedown',
  'escape', 'esc', 'insert', 'backtab', 'clear',
])

function isPrintable(k: ClientKeyEvent): boolean {
  return !k.ctrl && !k.meta && k.key.length > 0 && !SPECIAL.has(k.key) && !/^f\d{1,2}$/.test(k.key) && k.key.charCodeAt(0) !== 0x1b
}

function diffKey(s: FileState, k: ClientKeyEvent, props: NavProps, f: NavFile, post: (op: NavOp) => void): FileState {
  const { body } = dims(props)
  const hunks = parseHunks(f.diff?.hunks ?? '')
  const lastHunk = Math.max(0, hunks.length - 1)
  const key = k.key
  const goto = (hunk: number): FileState => ({ ...s, hunk: clamp(hunk, 0, lastHunk), diffTop: 0 })
  if (!NO_MODS(k)) return s
  if (key === 'left') {
    post({ op: 'diff' })

    return { ...s, hunk: 0, diffTop: 0 }
  }
  if (key === 'up') return goto(s.hunk - 1)
  if (key === 'down') return goto(s.hunk + 1)
  if (key === 'home') return goto(0)
  if (key === 'end') return goto(lastHunk)
  const step = Math.max(1, body - 2)
  const size = Math.max(0, (hunks[s.hunk]?.length ?? 1) - 1)
  const top = s.diffTop ?? 0
  if (key === 'pagedown') {
    // The rest of this hunk is longer than the window: scroll within it; otherwise on to the next hunk.
    return size - top > body ? { ...s, diffTop: top + step } : goto(s.hunk + 1)
  }
  if (key === 'pageup') return top > 0 ? { ...s, diffTop: Math.max(0, top - step) } : goto(s.hunk - 1)

  return s
}

function viewKey(s: FileState, k: ClientKeyEvent, props: NavProps, f: NavFile, post: (op: NavOp) => void): FileState {
  // No letter commands in view mode: typing goes to Claude Code's prompt.
  if (isPrintable(k)) {
    post({ op: 'type', text: k.key })

    return s
  }
  if (hasDiffView(f)) return diffKey(s, k, props, f, post)
  const key = k.key
  const { body } = dims(props)
  const viewRows = Math.max(1, body)
  if (!NO_MODS(k)) return s
  if (key === 'left') {
    post({ op: 'back' })

    return s
  }
  if (!isTextual(f)) return s
  if (key === 'right' || key === 'return' || key === 'enter') return enterEdit(s, props, f, post)

  const { start, last } = extent(f)
  const end = Math.max(start, last)
  const rendered = isRendered(f)
  const atEnd = (rendered ? s.top : s.line) >= end
  const atStart = (rendered ? s.top : s.line) <= start
  // Past the end of a page (or before its start) the next page is asked for; `sync` puts the cursor at its edge.
  const nextPage = (): FileState => {
    if (f.pageCount > 1 && f.page < f.pageCount - 1) post({ op: 'page', page: f.page + 1 })

    return s
  }
  const prevPage = (): FileState => {
    if (f.pageCount > 1 && f.page > 0) post({ op: 'page', page: f.page - 1 })

    return s
  }

  if (rendered) {
    // Rendered markdown scrolls by source lines (blank lines skipped, so each press moves something).
    const lines = extent(f).lines
    const at = (n: number): string => lines[n - start] ?? ''
    const scroll = (top: number): FileState => ({ ...s, top: clamp(top, start, end), line: clamp(top, start, end) })
    if (key === 'down') {
      if (atEnd) return s
      let t = s.top + 1
      while (t < end && at(t).trim() === '') t++

      return scroll(t)
    }
    if (key === 'up') {
      if (atStart) return s
      let t = s.top - 1
      while (t > start && at(t).trim() === '') t--

      return scroll(t)
    }
    if (key === 'pagedown') return atEnd ? nextPage() : scroll(s.top + Math.max(1, viewRows - 2))
    if (key === 'pageup') return atStart ? prevPage() : scroll(s.top - Math.max(1, viewRows - 2))
    if (key === 'home') return scroll(start)
    if (key === 'end') return scroll(end - viewRows + 1)

    return s
  }

  if (key === 'down') return setLine(s, props, f, s.line + 1)
  if (key === 'up') return setLine(s, props, f, s.line - 1)
  if (key === 'pagedown') return atEnd ? nextPage() : setPage(s, props, f, viewRows)
  if (key === 'pageup') return atStart ? prevPage() : setPage(s, props, f, -viewRows)
  if (key === 'home') return setLine(s, props, f, start)
  if (key === 'end') return setLine(s, props, f, end)

  return s
}

export function fileKey(state: FileState, k: ClientKeyEvent, props: NavProps, post: (op: NavOp) => void): FileState {
  const s = settle(state, props)
  if (s.buffer) return editKey(s, k, props, post)
  const f = props.file
  if (!f) return s

  return viewKey(s, k, props, f, post)
}

// --------------------------------------------------------------------------- pointer

/** The UTF-16 index in `text` whose display column is the largest one at most `target`. */
function colAt(text: string, target: number): number {
  let i = 0
  while (i < text.length) {
    const c = text.charCodeAt(i)
    const n = c >= 0xd800 && c <= 0xdbff && i + 1 < text.length ? 2 : 1
    if (displayCol(text, i + n) > target) return i
    i += n
  }

  return text.length
}

export function filePointer(state: FileState, p: ClientPointerEvent, props: NavProps, post: (op: NavOp) => void): FileState {
  const s = settle(state, props)
  if (p.type !== 'down' || p.button === 'right' || p.button === 'middle') return s
  const f = props.file
  const { body } = dims(props)
  if (p.y === body) {
    // The status line: its first item is the way back.
    if (s.buffer || !f || p.x >= 6) return s
    if (hasDiffView(f)) {
      post({ op: 'diff' })

      return { ...s, hunk: 0, diffTop: 0 }
    }
    post({ op: 'back' })

    return s
  }
  if (p.y < 0 || p.y >= body) return s
  if (s.buffer) {
    const b = s.buffer
    const { gw, vr, vc } = editGeom(props, b)
    const row = clamp(b.top + Math.floor(p.y), 0, b.lines.length - 1)
    const text = b.lines[row] ?? ''
    const col = colAt(text, Math.max(0, Math.floor(p.x) - gw) + b.left)
    const nb = scrollIntoView({ ...b, cursor: { row, col }, goalCol: displayCol(text, col), run: undefined }, vr, vc)

    return { ...s, buffer: nb, isDiscarding: false }
  }
  if (!f || !isTextual(f) || hasDiffView(f) || isRendered(f)) return s
  const { start, last } = extent(f)
  const line = s.top + Math.floor(p.y)
  if (line < start || line > last) return s

  return { ...s, line }
}

